import assert from "node:assert/strict";
import { formatCsvRow } from "./csv-exporter.mjs";
import { writeCsv } from "./csv-caller.mjs";

function parseCsv(input) {
  const records = [];
  let record = [];
  let field = "";
  let quoted = false;
  let afterQuote = false;

  for (let index = 0; index < input.length; index += 1) {
    const character = input[index];
    if (quoted) {
      if (character === '"') {
        if (input[index + 1] === '"') {
          field += '"';
          index += 1;
        } else {
          quoted = false;
          afterQuote = true;
        }
      } else {
        field += character;
      }
      continue;
    }

    if (afterQuote) {
      if (character === ",") {
        record.push(field);
        field = "";
        afterQuote = false;
        continue;
      }
      if (character !== "\r" || input[index + 1] !== "\n") {
        throw new Error("Unexpected data after quoted field or missing CRLF record ending");
      }
      record.push(field);
      records.push(record);
      record = [];
      field = "";
      afterQuote = false;
      index += 1;
      continue;
    }

    if (character === '"') {
      if (field !== "") {
        throw new Error("Quote inside an unquoted field");
      }
      quoted = true;
    } else if (character === ",") {
      record.push(field);
      field = "";
    } else if (character === "\r") {
      if (input[index + 1] !== "\n") {
        throw new Error("Bare CR outside a quoted field");
      }
      record.push(field);
      records.push(record);
      record = [];
      field = "";
      index += 1;
    } else if (character === "\n") {
      throw new Error("Bare LF outside a quoted field");
    } else {
      field += character;
    }
  }

  if (quoted) {
    throw new Error("Unterminated quoted field");
  }
  if (afterQuote || record.length > 0 || field !== "") {
    throw new Error("Every record must end with CRLF");
  }
  return records;
}

const rows = [
  ["id", "comment", "unicode", "empty-left", "empty-right"],
  ["7", "north, west", 'say "go"', "\u6771\u4EAC \u{1f6f0}\uFE0F", ""],
  ["8", "line one\nline two", "carriage\rreturn", "windows\r\nnewline", 'comma, and "quote"'],
  ["9", "", "plain", "", "end"],
  [""],
];

for (const fields of rows) {
  const serialized = formatCsvRow(fields);
  assert.ok(serialized.endsWith("\r\n"), "each formatted record must retain its CRLF terminator");
  assert.deepEqual(parseCsv(serialized), [fields]);
}

assert.deepEqual(parseCsv(writeCsv(rows)), rows, "the existing caller must preserve row and column order");
assert.deepEqual(parseCsv(writeCsv([])), [], "an empty row list must remain an empty CSV stream");
assert.throws(() => parseCsv('unquoted"quote\r\n'));
assert.throws(() => parseCsv('"unterminated\r\n'));
assert.throws(() => parseCsv('"closed"extra\r\n'));
assert.throws(() => parseCsv("valid,record\r\ntrailing"));
assert.throws(() => parseCsv("valid,record\n"));
console.log("5 row round-trips, caller order, empty stream, CRLF endings, and malformed/trailing-data checks passed");
